        "id": "hl-w69-12",
        "term": "A",
        "phonetic": "",
        "wordType": "academic",
        "meaningVi": "a) Population: housing (b) Fatigue: effort (c)  Congestion: space (d) Memory: knowledge (e)  Flood: thaw Giả sử bạn đang gặp khó khăn để tìm ra mối liên hệ giữa BANKRUPTCY và PROFIT. Hãy thử làm ngược lại: tìm mối quan hệ của mỗi cặp từ và hãy khám phá xem mối lien hệ nào cũng được áp dụng cho cặp từ được in hoa. Phương pháp này được trình bày như sau: BANKRUPTCY: PROFIT (Phá sản: Lợi nhuận (A) Population: Housing (Dân số: Nhà cửa ): Mối quan hệ là “A cần đến B” vì dân số cần đến nhà ở. Nhưng phá sản không cần đến lợi nhuận; một khi phá sản xảy ra thì quá muộn để cho lợi nhuận thật sự hữu ích. Do đó chọn A là sai. (B) Fatigue: Effort (Mệt mỏi: Cố gắng ): Mối quan hệ là: “A phát sinh là do quá nhiều B” (Mệt mỏi phát sinh là do quá nhiều cố gắng.) Vì phá sản không thể phát sinh từ quá nhiều lợi nhuận -> Chọn B là sai. (C) Congestion: Space (Sự chật chội: Khỏang không gian ): Mối quan hệ là “A phát xuất từ sự kiện B quá ít”: Chật chội phát xuất từ việc quá ít khỏang trống, không gian.) Phá sản phát xuất từ việc có quá ít lợi nhuận. Chọn C có vẻ đúng. Nhưng chúng ta hãy thử xem xét các lựa chọn còn lại. (D)Memory: Knowledge (Ký ức: Kiến thức mới ): Mối quan hệ là: “A chứa B” (Ký ức chứa đựng, tích trữ kiến thức.) Bởi vì phá sản không chứa đựng, tích trữ lợi nhuận -> C là sai. (E) Flood: Thaw (Lụt: Băng tan): Mối quan hệ là “A có thể xuất phát từ B” (Lục có thể xuất phát từ bằng tuyết tan ra ) Nhưng phá sản không xuất phát từ lợi nhuận. Do đó chọn E là sai. IV)                  CÂU HỎI LỌAI SUY – ĐA TUYỂN: Có câu hỏi lọai suy đa tuyển mà trong đó bạn được cho một cặp từ đầu tiên và từ thứ nhất của cặp thứ nhì bằng cách chọn một trong số 5 từ được cho (đa tuyển ). Bài tập sau đây giới thiệu cùng bạn lọai câu hỏi lọai suy này. Exercises 3: Write the letter of the word that best completes the analogy",
        "meaningEn": "",
        "example": "",
